"""运行状态 API。"""
import time

from fastapi import APIRouter

router = APIRouter(prefix='/status', tags=['status'])


def _mask_token(token: str) -> str:
    """脱敏显示密钥。"""
    if not token:
        return ''
    if len(token) <= 16:
        return '****'
    return token[:8] + '****' + token[-4:]


@router.get('')
async def get_status():
    """运行状态（同 /status 指令逻辑）。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    uptime = int(time.time() - app.started_at)
    token_status = app.token_meter.status()

    # 能力计数
    capability_counts = {
        'skills': len(app.skills.list_skills()),
        'metaskills': len(app.metaskills.list_metaskills()),
        'tools': len(app.tools.list_tools()),
        'commands': len(app.commands.list_commands()),
    }

    # 记忆统计
    memory_stats = app.memory.stats() if hasattr(app.memory, 'stats') else {}

    # 子 Agent Provider 状态
    subagent_info = {
        'providers': app.subagent_manager.discover(),
        'default': app.subagent_manager._default_provider,
    }

    # 凭据状态
    config = app.config
    has_token = bool(config.ws_token)
    credentials_data = {
        'configured': has_token,
        'agent_id': config.agent_id if has_token else '',
        'token_masked': _mask_token(config.ws_token) if has_token else '',
    }

    # 引导信息（未配置 Token 时提供）
    guide_data = None if has_token else {
        'message': '配置密钥以解锁平台协同/接单模式',
        'register_url': 'https://openchiip.com/register',
        'configure_cmd': ('curl -X PUT http://127.0.0.1:%d/api/v1/credentials '
                          '-H "Content-Type: application/json" '
                          '-d \'{"token": "your-token"}\'' % config.port),
    }

    return {
        'agent_id': config.agent_id,
        'uptime': uptime,
        'llm_configured': config.llm_configured,
        'model_name': config.model_name,
        'fast_model_name': getattr(config, 'fast_model_name', ''),
        'token': {
            'used': token_status.get('used', 0),
            'month': token_status.get('month', ''),
        },
        'capabilities': capability_counts,
        'memory': memory_stats,
        'subagents': subagent_info,
        'ws_connected': app.ws_client.connected if app.ws_client else False,
        'run_mode': getattr(config, 'run_mode', 'local'),
        'mode_label': {
            'local': '本地模式',
            'collaborative': '平台协同',
            'order': '接单模式',
        }.get(getattr(config, 'run_mode', 'local'), '本地模式'),
        'credentials': credentials_data,
        'guide': guide_data,
        'version': '0.0.30',
    }
